import {feedMesh,feedCylinder,feedTransform,feedPuckBody,feedContinuousSocket,feedSocketBody,feedIntegralSocket} from './feed-solids.js';
export const FEED={revision:7,engagement:18,minEngagement:16,maxEngagement:19,puckRadius:22};
const FEED_TAU=2*Math.PI;
const fz=(r,p)=>r*r/(4*p.diameter*p.fd);
export function feedDatum(p){const r=p.diameter/2-20;return{r,front:fz(r,p),rear:fz(r,p)-p.thickness-3,slope:r/(2*p.diameter*p.fd),holes:[]};}
export function feedFits(p,n,rows){if(!p.feedMode)return true;if(n%p.feedLegs)return false;const d=feedDatum(p),r0=45+(rows-1)*(p.diameter/2-45)/rows;return d.r-23>Math.max(78,r0+8)&&d.r*Math.sin(Math.PI/n)>27;}
function hyperbola(p,ratio){
 const f=p.diameter*p.fd,g=p.backFocus,zv=f*ratio,zc=(f+g)/2,c=(f-g)/2,a=zv-zc,b2=c*c-a*a;
 if(!(g<0&&a>0&&a<c&&b2>0))throw Error('Secondary vertex must lie between the two-focus midpoint and primary focus.');
 const surface=r=>zc+a*Math.sqrt(1+r*r/b2),R=p.diameter/2,depth=fz(R,p);let lo=0,hi=R;for(let i=0;i<70;i++){const r=(lo+hi)/2;if(surface(r)<f+(depth-f)*r/R)lo=r;else hi=r;}
 const intercept=(lo+hi)/2,radius=intercept*1.04,edgeZ=surface(radius),backZ=zv+10,returnRadius=intercept*(fz(60,p)-g)/(surface(intercept)-g);
 return{primaryFocus:f,backFocus:g,vertex:zv,center:zc,c,a,b2,interceptRadius:intercept,radius,edgeZ,backZ,returnRadius,surface,ratio};
}
export function cassegrainGeometry(p){
 let s,target=null;if(p.autoSecondary&&p.frequencyGHz>0){target=Math.max(56,p.secondaryWaves*299.792458/p.frequencyGHz);if(target>p.diameter*.25)throw Error('Requested wavelength-sized secondary exceeds 25% of dish diameter. Use prime focus, a larger dish, or manual secondary geometry for an explicitly experimental layout.');let lo=Math.max(.5001,(p.diameter*p.fd+p.backFocus)/(2*p.diameter*p.fd)+.001),hi=.98;for(let i=0;i<60;i++){const mid=(lo+hi)/2;if(hyperbola(p,mid).radius*2>target)lo=mid;else hi=mid;}s=hyperbola(p,(lo+hi)/2);}else s=hyperbola(p,p.secondaryPosition);
 if(s.radius<28-1e-7||s.radius>p.diameter*.125+1e-7)throw Error('Secondary must be at least 56 mm across and no more than 25% of the dish diameter for this compact support.');
 if(s.returnRadius>13.5)throw Error('Returned ray bundle does not clear the 30 mm hub with 1.5 mm radial margin. Move the rear focus toward the vertex.');
 return{...s,targetDiameter:target};
}
export function feedGeometry(p,layout){
 if(!p.feedMode)return null;const d=feedDatum(p),lambda=p.frequencyGHz>0?299.792458/p.frequencyGHz:null,secondary=p.feedMode===2?cassegrainGeometry(p):null;
 const offset=p.feedMode!==1?0:p.phaseUnits===1?(lambda===null?NaN:p.phaseOffset*lambda):p.phaseOffset;if(!Number.isFinite(offset))throw Error('Enter a frequency for a phase-center offset specified in wavelengths.');
 const lowerZ=d.rear,topRadius=18;
 const requiredFace=secondary?lowerZ+(secondary.edgeZ+10-lowerZ)*(d.r-topRadius)/(d.r-secondary.radius-7)-8:0;
 const stemHeight=secondary?Math.max(30,5*Math.ceil((requiredFace-secondary.backZ)/5)):0;
 const carrierFace=secondary?secondary.backZ+stemHeight:p.diameter*p.fd-offset,upperZ=carrierFace+8;
 const distance=Math.hypot(d.r-topRadius,upperZ-lowerZ),ux=(d.r-topRadius)/distance,uz=(upperZ-lowerZ)/distance;
 // The lower datum lies under the petal. Solve the actual curved-face crossing,
 // rather than borrowing the former separate shoe's fixed 22 mm entrance.
 let lo=0,hi=distance;for(let i=0;i<64;i++){const t=(lo+hi)/2;if(lowerZ+uz*t<fz(d.r-ux*t,p))lo=t;else hi=t;}
 const lowerEntrance=(lo+hi)/2,upperEntrance=22;
 const cut=distance-lowerEntrance-upperEntrance+2*FEED.engagement;
 if(upperZ-lowerZ<15||distance<60||cut>600)throw Error('Rod geometry is outside the compact fitting envelope: require at least 15 mm rise, 60 mm span and at most 600 mm cut.');
 // Conservative single-rod cantilever screening, NOT a full truss/load model.
 // E=69 GPa; full entered payload acts transversely on one rod; 1 mm or lambda/50 target.
 const targetDeflection=Math.min(1,lambda===null?1:lambda/50),load=p.feedPayload/1000*9.80665,L=distance-lowerEntrance-upperEntrance;
 const deflection=diameter=>load*L**3/(3*69000*(Math.PI*diameter**4/64));
 const diameter=p.rodDiameter||[4,5,6,6.35,8].find(d=>deflection(d)<=targetDeflection);
 if(!diameter)throw Error('No 4–8 mm solid aluminum rod meets the screening deflection budget. Reduce payload/span or engineer a tubular support.');
 const phase=p.staggerRings?((layout.rows-1)%2)*Math.PI/layout.n:0,legs=Array.from({length:p.feedLegs},(_,i)=>{const angle=phase+i*FEED_TAU/p.feedLegs;const lower=[d.r*Math.cos(angle),d.r*Math.sin(angle),lowerZ],upper=[topRadius*Math.cos(angle),topRadius*Math.sin(angle),upperZ],axis=upper.map((v,k)=>(v-lower[k])/distance);return{number:i+1,angle,lower,upper,lowerRodEnd:lower.map((v,k)=>v+axis[k]*(lowerEntrance-FEED.engagement)),upperRodEnd:upper.map((v,k)=>v-axis[k]*(upperEntrance-FEED.engagement)),lowerFaceCrossing:lower.map((v,k)=>v+axis[k]*lowerEntrance),pivotDistance:distance,lowerEntrance,upperEntrance,cutLength:cut};});
 if(secondary){const rr=secondary.radius+diameter/2+1,z=lowerZ+(upperZ-lowerZ)*(d.r-rr)/(d.r-topRadius);if(z<secondary.edgeZ+3+diameter/2+1)throw Error('Rod path crowds the secondary edge. Change secondary position, rear focus or dish geometry.');}
 const warnings=['Prototype: no wind, payload or RF performance rating. Small radial screws require physical slip and warm-creep tests.'];
 if(p.feedLegs===4)warnings.push('Fit the fourth rod last without preload; never use it to pull a warped petal into alignment.');
 if(!lambda)warnings.push('Frequency unspecified: wavelength-dependent dimensions and RF tolerances are unavailable.');
 if(p.feedMode===1&&offset===0)warnings.push('Zero phase-center offset is a placeholder; specify the actual feed datum.');
 if(deflection(diameter)>targetDeflection)warnings.push('Selected rod exceeds the conservative deflection screening budget; use larger stock or reduce payload.');
 if(secondary){warnings.push('Hyperbolic ray geometry is not electromagnetic validation. A frequency-specific rear feed remains required.');if(lambda&&2*secondary.radius/lambda<5)warnings.push('Secondary is below five wavelengths: diffraction requires full-wave or hybrid electromagnetic analysis.');}
 return{mode:p.feedMode===1?'prime-focus':'cassegrain',legs,datum:d,carrierFace,upperZ,lowerZ,cutLength:cut,lowerEntrance,upperEntrance,pivotDistance:distance,rodAngle:Math.atan2(upperZ-lowerZ,d.r-topRadius)*180/Math.PI,phase,secondary,stemHeight,offset,rodDiameter:diameter,lambda,targetDeflection,screenDeflection:deflection(diameter),surfaceRmsBudget:lambda?lambda/40:null,warnings};
}
const transform=(mesh,fn)=>({v:mesh.v.map(fn),f:mesh.f});
const flip=mesh=>transform(mesh,([x,y,z])=>[x,-y,-z]);
function socketFrame(A,B,azimuth=0){const dx=B[0]-A[0],dz=B[2]-A[2],L=Math.hypot(dx,dz),u=dx/L,w=dz/L;return([x,y,z])=>{const X=A[0]+w*x+u*z,Y=A[1]+y;return[Math.cos(azimuth)*X-Math.sin(azimuth)*Y,Math.sin(azimuth)*X+Math.cos(azimuth)*Y,A[2]-u*x+w*z];};}
export function petalRodSocket(p,layout,backFn){const g=feedGeometry(p,layout);return feedIntegralSocket(p,g,layout.n,backFn);}
export function appendFeedParts(m,api){
 if(!m.p.feedMode)return;const{patch,printMesh,bounds}=api,p=m.p,g=feedGeometry(p,m.layout),d=g.datum;m.feed=g;
 const add=(id,name,mesh,qty,angles=[0],printing=null)=>{const pm=printing||printMesh(mesh),dim=bounds(pm).size;if(dim[0]>p.bedX-2*p.margin||dim[1]>p.bedY-2*p.margin||dim[2]>p.bedZ-2)throw Error(name+' does not fit the print volume.');const part={id,name,mesh,print:pm,output:pm,supportMeshes:[],dim,qty,kind:'feed',row:-1,angle:0,bedRotation:0,spec:{holes:[]}};m.parts.push(part);for(const a of angles)m.instances.push({part,a});return part;};
 const angles=g.legs.map(x=>x.angle);
 const sleeve=feedSocketBody(g.rodDiameter);
 let puck=feedPuckBody(0,Boolean(g.secondary)),cuts=g.secondary?[]:[feedCylinder([0,0,-19],[0,0,0],16,64)];
 const core=puck,upperSocket=feedContinuousSocket(g.rodDiameter,p.rodClearance,-1);
 // Load carrier nuts outward/upward, away from its center and secondary stem.
 for(const a of angles){const fn=socketFrame([18,0,8],[d.r,0,g.lowerZ-g.carrierFace],a);puck=puck.union(core.union(feedTransform(sleeve,fn)).hull());cuts.push(...upperSocket.cuts.map(c=>feedTransform(c,fn)));}
 cuts.push(feedCylinder([0,0,g.secondary?g.secondary.backZ-g.carrierFace-1:-20],[0,0,20],g.secondary?2.3:6,32));
 for(let i=0;i<p.feedLegs;i++){const a=g.phase+(i+.5)*FEED_TAU/p.feedLegs,x=12*Math.cos(a),y=12*Math.sin(a);cuts.push(feedCylinder([x,y,-1],[x,y,17],1.7,20));}
 if(g.secondary)puck=puck.union(feedCylinder([0,0,g.secondary.backZ-g.carrierFace],[0,0,1],9,32));
 for(const c of cuts)puck=puck.subtract(c);
 // Build the carrier in local coordinates to keep Float32 loft input precise
 // even for large focus offsets. Add its assembled height after meshing.
 const pm=transform(feedMesh(puck),([x,y,z])=>[x,y,z+g.carrierFace]);add('feed-puck','Feed · slim lobed carrier',pm,1,[0],printMesh(flip(pm)));
 if(g.secondary){const s=g.secondary,back=(x,y)=>{const r=Math.hypot(x,y),t=Math.min(1,Math.max(0,(r-10)/5));return Math.max(s.surface(r)+3,s.backZ*(1-t)+(s.surface(r)+3)*t);};const h={r0:0,r1:2.8,a0:0,a1:FEED_TAU},front=(x,y)=>s.surface(Math.hypot(x,y)),mesh=patch({r0:0,r1:s.radius,a0:0,a1:FEED_TAU,levels:[front,(x,y)=>front(x,y)+.3*(back(x,y)-front(x,y)),back],layers:[{},{holes:[h]}],gridBoxes:[h],extraR:[10,15]},p);add('secondary-reflector','Secondary · 3 mm shell / center boss',mesh,1,[0],printMesh(flip(mesh)));}
}
export function feedManifest(m){if(!m.feed)return{enabled:false};const g=m.feed,s=g.secondary;return{enabled:true,revision:FEED.revision,mode:g.mode,legs:m.p.feedLegs,rod_diameter_mm:g.rodDiameter,stock:'smooth solid aluminum rod (screen assumes E = 69 GPa)',cut_length_mm:g.cutLength,socket_end_span_mm:g.pivotDistance,nominal_insertion_each_end_mm:18,carrier_engagement_range_mm:[16,19],petal_attachment:'integrated underside through-bore and short M3 heat-set insert side screw',petal_bore_roof:'45-degree shoulders and 0.8 mm bridge relative to petal print-up',carrier_lower_face_z_mm:g.carrierFace,phase_center_offset_mm:g.offset,frequency_GHz:m.p.frequencyGHz||null,wavelength_mm:g.lambda,surface_rms_screen_mm:g.surfaceRmsBudget,rod_deflection_screen_mm:g.screenDeflection,rod_deflection_budget_mm:g.targetDeflection,payload_input_g:m.p.feedPayload,puck_core_diameter_mm:44,lower_bore_entrance_mm:g.lowerEntrance,upper_bore_entrance_mm:g.upperEntrance,adapter_bolt_circle_mm:24,adapter_bolts:`${m.p.feedLegs} × M3 midway between rods; feed-specific adapter required`,legs_geometry:g.legs,secondary:s?{primary_focus_z:s.primaryFocus,rear_focus_z:s.backFocus,vertex_z:s.vertex,vertex_ratio:s.ratio,diameter_mm:2*s.radius,target_diameter_mm:s.targetDiameter,front_surface:'z = center + a * sqrt(1 + r^2 / b^2)',center:s.center,a:s.a,b:Math.sqrt(s.b2),back_boss_z:s.backZ,return_bundle_radius_mm:s.returnRadius}:null,hardware:feedHardware(m),warnings:g.warnings};}
export function rodCSV(m){if(!m.feed)return'';const g=m.feed;return 'leg,stock,diameter_mm,datum_span_mm,lower_face_crossing_mm,upper_bore_entrance_mm,insertion_mark_each_mm,cut_length_mm,cut_length_inches,azimuth_degrees,rod_elevation_degrees,lower_rod_end_z_mm,upper_rod_end_z_mm\n'+m.feed.legs.map(l=>[l.number,'smooth solid aluminum',m.feed.rodDiameter,l.pivotDistance.toFixed(3),g.lowerEntrance.toFixed(3),g.upperEntrance.toFixed(3),18,l.cutLength.toFixed(3),(l.cutLength/25.4).toFixed(4),(l.angle*180/Math.PI).toFixed(3),m.feed.rodAngle.toFixed(3),l.lowerRodEnd[2].toFixed(3),l.upperRodEnd[2].toFixed(3)].join(',')).join('\n')+'\n';}
export function feedHardware(m){if(!m.feed)return[];const n=m.p.feedLegs;return[
 {item:'petal rod-retention screw',spec:'M3 × 12',quantity:n,note:'Headless side set screw into a short M3 insert; rounded tip against solid rod.'},
 {item:'petal retention insert',spec:'short M3 / maximum 4 mm / compatible with 4.2 mm pilot',quantity:n,note:'Heat-set from the side, recessed 0.5 mm. Test insert fit before printing the dish.'},
 {item:'carrier rod-retention screw',spec:'M3 × 10',quantity:n,note:'Real M3 hex nut in carrier side pocket.'},
 {item:'carrier retention nut',spec:'M3 hex / 5.5 mm AF / 2.4 mm thickness',quantity:n,note:'Carrier pocket allows 5.8 mm AF.'},
 ...(m.feed.secondary?[{item:'secondary screw',spec:`M4 × ${m.feed.stemHeight+25}`,quantity:1,note:`${m.feed.stemHeight+16} mm puck/stem stack + 4 mm metal washer/spacer stack; nominal 5 mm entry.`},{item:'M4 washer',spec:'1 mm thick',quantity:4,note:'4 mm total metal spacer/washer stack'},{item:'secondary insert',spec:'short M4 / maximum 6 mm / compatible with 5.6 mm pilot',quantity:1,note:'7 mm blind pocket; insert 0.5 mm below boss face'}]:[])];}
export function feedHardwareCSV(m){const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';return 'item,specification,quantity,grip_mm,note\n'+feedHardware(m).map(x=>[x.item,x.spec,x.quantity,x.grip_mm?.toFixed(3),x.note].map(quote).join(',')).join('\n')+'\n';}
export function feedGuide(m){if(!m.feed)return'';const g=m.feed;return `# PETAL compact rod support · ${g.mode}\n\nAccessory revision 7: rods fasten directly into the underside of the selected outer petals. There are no rim shoes, backing plates or paired mounting bolts. Regenerate the mount petals, carrier and rod cuts as a matching kit; earlier rods and petals do not interchange. Seam/hub interface remains revision 12. Changing rod count may change segmentation.\n\n## Rods and attachment\n\n${m.p.feedLegs} × Ø${g.rodDiameter} mm smooth SOLID aluminum rods; nominal cut ${g.cutLength.toFixed(2)} mm each. The petal has an angled through-hole and a small continuous underside saddle, chamfered into the shell. A side M3×12 headless set screw bears on the rod through a short M3 heat-set insert (maximum 4 mm long, compatible with the 4.2 mm pilot). The carrier retains its hex nuts. No printed threads or extra petal mounting bolts.\n\nRod elevation is ${g.rodAngle.toFixed(2)}°. The lower face crossing is solved from the dish curvature, not a fixed shoe height. Cut = datum span − lower face crossing − upper entrance + 36 mm. Mark 18 mm from each rod end. At the petal, align the mark with the center of the front opening; the through-hole has no floor and the rear end may protrude. This insertion mark is not a claim of 18 mm continuous plastic bearing. At the carrier, retain 16–19 mm engagement without bottoming the rod. RODS.csv gives the actual angles, positions and cuts. Trial-fit long stock before final trimming.\n\n## Printing and assembly\n\nThe integrated saddle is designed for the petal's existing side-print orientation. Its compact circular tapers blend into the underside. The rod bore has 45° roof shoulders and a 0.8 mm bridge aligned to print-up. The side screw and insert pilot are circular, nearly vertical in the print orientation. Keep this exported orientation. Nominal diametral rod clearance is ${m.p.rodClearance.toFixed(2)} mm; print one mount petal and verify fit first. The circular lower arc locates the rod; the short roof relief clears the full specified diameter.\n\nHeat-set the short M3 insert from the side, recessed 0.5 mm; then insert the rod through the petal and fit the side screw. Keep the screw loose while aligning the carrier with a height/centering jig. Fit the fourth rod last without preload. Tighten progressively and mark the rods to reveal slip. Petal inserts and carrier hex nuts are distinct items in FEED-HARDWARE.csv.\n\nThe existing carrier prints top-face down and still needs slicer review/localized support for circular bores and hex-nut roofs. The new petal socket's support-free geometry does not certify the carrier or secondary as support-free. PCTG and ASA still require a fit/slip/temperature test of the printed joint; resin data alone does not rate the assembled part. Use locally solid socket walls and a suitable material profile. Avoid hollow tubing with point screws unless separately engineered for crushing and stiffness.\n\nThe carrier has ${m.p.feedLegs} M3 adapter holes on 24 mm BCD and ${g.secondary?'a central M4 clearance hole':'a 12 mm cable opening'}. A feed-specific adapter and its hardware remain separate. Strain-relieve the cable along a rod. Measure height/centering/tilt before and after tightening and warm soaking.\n\n## Frequency and optical meaning\n\n${g.lambda?`Frequency ${m.p.frequencyGHz} GHz gives wavelength ${g.lambda.toFixed(3)} mm. Surface RMS screening target λ/40 = ${g.surfaceRmsBudget.toFixed(3)} mm, including printing, assembly and metallization errors. This is a design budget, not measured accuracy. The rod screening budget is min(1 mm, λ/50) = ${g.targetDeflection.toFixed(3)} mm.`:'Frequency is unknown; enter it to enable wavelength-based dimensions and accuracy guidance.'}\n\nFrequency alone does not move the focus of a fixed parabola. Prime focus remains f = D × f/D = ${m.focal.toFixed(3)} mm. A phase-center offset can be entered in mm or wavelengths ONLY when supported by the chosen feed design; scaling a generic unknown feed is not valid. The puck lower-face datum is z=${g.carrierFace.toFixed(3)} mm; phase-center offset is ${g.offset.toFixed(3)} mm along +z.\n\n${g.secondary?`The secondary is a convex hyperboloid toward the main dish: vertex z=${g.secondary.vertex.toFixed(3)} mm, diameter ${(2*g.secondary.radius).toFixed(3)} mm, rear focus z=${g.secondary.backFocus.toFixed(3)} mm. Automatic mode targets the entered secondary wavelength count (minimum 56 mm mechanical diameter), solves its position and then recalculates rod lengths and angles. Above 25% dish diameter it rejects the combination; choose prime focus or a larger dish. These are engineering screening limits, not optimized RF dimensions. The 3 mm reflective shell has a central 10 mm boss with one blind Ø5.6×7 mm insert pocket. Install a short M4 insert at least 0.5 mm recessed, maximum 6 mm long; use M4×${g.stemHeight+25} with a 4 mm metal washer/spacer stack through the ${g.stemHeight+16} mm puck/stem stack. Verify actual engagement and leave the reflective face intact. Secondary prints with its boss down; support the surrounding back shell in the slicer. The rear RF feed, phase center, polarization and illumination must be designed separately.`:'Place the actual feed PHASE CENTER at the focus, not automatically its mouth or flange. A zero offset remains unverified. The feed points toward the main dish.'}\n\nAuto rod sizing screens 4, 5, 6, 6.35 and 8 mm SOLID aluminum using E=69 GPa and a deliberately conservative single cantilever with the entire entered ${m.p.feedPayload} g payload applied transversely over the exposed span: δ=FL³/(3EI). Selected-rod result ${g.screenDeflection.toFixed(3)} mm. Include feed/secondary, puck, adapter and cable loads in the payload input; wind, joint compliance, resonance and creep are excluded. This is not an allowable-load calculation or an RF guarantee. Manual diameter overrides retain an over-budget warning.\n\n${g.warnings.map(w=>'- '+w).join('\n')}\n\nCoat the dish-facing secondary surface with continuous bonded aluminum/copper foil or a verified conductive coating; ordinary metallic paint is not sufficient evidence of RF conductivity. Keep datums, bores and the boss back clean. Surface seams/wrinkles count toward the RF error budget. Test one assembled leg for slip and creep, then the complete assembly at several elevations before committing to a full outdoor installation.\n`;}
